// Scratch exploration: what do additional e-rara SRU queries offer for Zürich?
// Not part of the repo.
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { createHash } from 'node:crypto';

const UA = 'Kartenzeit/1.0 (exploration; contact: project maintainers)';
const CACHE = '/tmp/explore-cache/';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function decode(s) {
  return String(s || '')
    .replace(/&#x([0-9a-f]+);/gi, (_, hex) => String.fromCodePoint(parseInt(hex, 16)))
    .replace(/&#(\d+);/g, (_, num) => String.fromCodePoint(Number(num)))
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .trim();
}
const first = (xml, tag) => {
  const m = xml.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`));
  return m ? decode(m[1]) : null;
};
const all = (xml, tag) =>
  [...xml.matchAll(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`, 'g'))].map((m) => decode(m[1]));

async function get(url, as = 'text') {
  const hash = createHash('sha1').update(url).digest('hex').slice(0, 20);
  const file = CACHE + hash + (as === 'json' ? '.json' : '.txt');
  try {
    const cached = await readFile(file, 'utf8');
    return as === 'json' ? JSON.parse(cached) : cached;
  } catch {}
  const res = await fetch(url, { headers: { 'user-agent': UA } });
  if (!res.ok) throw new Error(`${res.status} ${url}`);
  const body = as === 'json' ? await res.json() : await res.text();
  await mkdir(CACHE, { recursive: true });
  await writeFile(file, as === 'json' ? JSON.stringify(body) : body);
  return body;
}

function sruUrl(cql, start = 1) {
  return (
    `https://www.e-rara.ch/sru?operation=searchRetrieve&version=1.2&query=${encodeURIComponent(cql)}` +
    `&startRecord=${start}&maximumRecords=100&recordSchema=mods`
  );
}

function parseSruRecord(chunk) {
  const extra = (chunk.match(/<srw:extraRecordData[\s\S]*?<\/srw:extraRecordData>/) || [''])[0];
  const titleId = first(extra, 'vl:id');
  if (!titleId) return null;
  const genres = all(chunk, 'genre');
  const w3c = (chunk.match(/<dateIssued encoding="w3cdtf"[^>]*>(\d{4})/) || [])[1];
  return {
    titleId,
    corpus: first(extra, 'vl:prefix') || null,
    signature: first(extra, 'vl:signature') || null,
    title: first(chunk, 'title') || '',
    year: Number(w3c) || Number((first(chunk, 'dateIssued') || '').match(/\d{4}/)?.[0]) || null,
    isMap: genres.some((g) => /^(map|altkarte)$/i.test(g)),
    genres,
    coordinates: first(chunk, 'coordinates') || null,
    creators: all(chunk, 'namePart').filter(Boolean),
  };
}

async function sruSearch(cql) {
  const hits = [];
  for (let start = 1; start <= 400; start += 100) {
    const xml = await get(sruUrl(cql, start));
    const chunks = [...xml.matchAll(/<srw:record>([\s\S]*?)<\/srw:record>/g)].map((m) => m[1]);
    if (!chunks.length) break;
    for (const c of chunks) {
      const hit = parseSruRecord(c);
      if (hit) hits.push(hit);
    }
    if (chunks.length < 100) break;
    await sleep(150);
  }
  return hits;
}

const box = async () => {
  const d = await get(
    'https://api3.geo.admin.ch/rest/services/api/SearchServer?searchText=Z%C3%BCrich&type=locations&origins=kantone&sr=4326&limit=1',
    'json',
  );
  const m = (d?.results?.[0]?.attrs?.geom_st_box2d || '').match(/BOX\(([-\d.]+) ([-\d.]+),([-\d.]+) ([-\d.]+)\)/);
  return m ? { west: +m[1], south: +m[2], east: +m[3], north: +m[4] } : null;
};

function covers(win, word) {
  const m = String(word || '').match(/([-\d.]+)\s*\/\s*([-\d.]+)\s*\/\s*([-\d.]+)\s*\/\s*([-\d.]+)/);
  if (!m) return { ok: true, lat: null, lon: null };
  const [lat1, lat2, lon1, lon2] = m.slice(1).map(Number);
  const lat = (lat1 + lat2) / 2;
  const lon = (lon1 + lon2) / 2;
  return { ok: lat >= win.south && lat <= win.north && lon >= win.west && lon <= win.east, lat, lon };
}

