    creators: candidate.creators.length ? candidate.creators : [],
    providerId: 'e-rara',
    institution: institution || (candidate.zuz ? 'Zentralbibliothek Zürich' : 'ETH-Bibliothek Zürich'),
    rights: candidate.rights || 'PDM 1.0',
